-- GENERATED by `wfj generate` from data/gossip/gossip-2f.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["2f091418286d3b44"] = { "Cerchi le benedizioni del Signore del Vento?", "." },
  ["2f10642dd904156f"] = { "Ti saluto, {race}.", "." },
  ["2f18362adab2b04b"] = { "<Gli schemi complicati sono troppo per le tue modeste capacità di ingegneria.>", "." },
  ["2f1fe33adea234f2"] = { "Yeee hawww! La flotta di Mulverick è pronta a scatenarsi. Tutti i soldati dell'⟦Horde=Orda⟧ in grado di combattere devono richiedere un faro e fare del loro meglio per piantarlo, così che i miei Calcaguerra possano orientarsi per l'assalto aereo.", "." },
  ["2f228cc32a5a6d0f"] = { "Muori! Non libererai Myzrael!", "." },
  ["2f22a41595777a25"] = { "Grazie per essere la mia prossima vittima!", "." },
  ["2f2e2a9d73df1dec"] = { "Grazie per le provviste, {name}!", "." },
  ["2f2ec0662a30f4a9"] = { "%s esamina il ⟦Searing Collar=Collare Rovente⟧...", "." },
  ["2f30d2f858e96792"] = { "Con piacere...", "." },
  ["2f3173f2d1f40847"] = { "La morte è l'unica via di fuga!", "." },
  ["2f31e22489c6f180"] = { "Con i materiali che trovo qui fuori posso realizzare cose straordinarie. Per la barba di Muradin, su queste colline ci sono creature fantastiche! Va' a dargli qualche botta, {name}, e riportami qualche bella storia.", "." },
  ["2f349dbc5dc94a08"] = { "Il vascello della rinascita deve essere rinforzato con l'elementio. Conosco una sola fonte di questo minerale: i piani elementali, nel cuore del nostro mondo.\n\nC'è qualcuno, un Earthshaper, che potrebbe saperne più di me su come procurarsi cose del genere. Devi trovare questo Earthshaper!", "." },
  ["2f3b7a3810dfb218"] = { "Questo kodo non somiglia per niente alla bestia che avevo attirato all'inizio! Chissà se il Kodoambulatore si può usare su di me.", "." },
  ["2f3f907fbb253fd9"] = { "Sembra che l'amore aleggi nel vento. Spero che non mi passi accanto senza fermarsi.", "." },
  ["2f43aa16ded6c892"] = { "Dev'essere nell'ultima cella. A meno che... non l'abbiano ucciso.", "." },
  ["2f469ce17223b464"] = { "Pescare è facilissimo. Prendi una canna con la lenza, magari ci metti un po' d'esca, e la lanci in acqua. Vedrai che i pesci cominceranno ad abboccare.", "." },
  ["2f49a04cfed729d6"] = { "Guarda, <druido/druida>. La terra respira ancora. Brama di essere purificata.", "." },
  ["2f4ad1e24a397d4a"] = { "Niente di meglio della sensazione di qualcosa di morto che ti si struscia addosso. Per trovare Shelene Rhobart, prendi la strada che esce dal paese verso sud-est, poi gira a est all'incrocio. Si trova in un piccolo accampamento poco più avanti lungo la strada.", "." },
  ["2f52f9dc3a2f157b"] = { "Chi sono i Terrigeni?", "." },
  ["2f565c7e0937fb2d"] = { "È una conoscenza più profonda delle vie dello stregone che bramo.", "." },
  ["2f616e3325bfef70"] = { "Oh, adesso mi hai fatto proprio arrabbiare!", "." },
  ["2f6a2126759dba68"] = { "%s fa un respiro profondo...", "." },
  ["2f780d2cc98b70e1"] = { "Benvenut<o/a> negli uffici del Registro delle Gilde di ⟦Stormwind=Roccavento⟧. Come posso aiutarti oggi?", "." },
  ["2f8482c76a801589"] = { "Salve, {class}. Da quanto mi è stato detto, è stato raccolto tutto, e tutto il materiale per la guerra viene spedito a ⟦Silithus=Silitus⟧ proprio ora. Dovrebbe arrivare tutto in meno di $2113w giorni. Una volta fatto, e suonato il gong con lo Scettro delle Sabbie Mutevoli, la guerra comincerà davvero.", "." },
  ["2f884f5078cf93d1"] = { "Salute. Cerchi istruzione nell'arte della guerra?", "." },
  ["2f8a4925bb5254ed"] = { "Continua a infilarmisi la sabbia tra le dita dei piedi.", "." },
  ["2f8b54204b0fd657"] = { "Mi occupo di sartoria, di mestiere. \r\n\nSenti, straniero, ti dico una cosa. Portami tutte le pietre del vento in più che trovi e condividerò con te la mia merce. Ho una bella scorta di indumenti Al'aketh qui. Di' quel che vuoi sulla follia del culto, ma devi ammettere che hanno un certo senso dello stile.\r\n\nO meglio, ce l'ho io, visto che ho disegnato quasi tutti i loro abiti.", "." },
  ["2fa46bc493329f02"] = { "Salve, <cittadino/cittadina>. Hai l'aria di <un/una> <uomo/donna> con uno scopo: hai affari con l'esercito di ⟦Stormwind=Roccavento⟧?", "." },
  ["2fab619dbf13f7a3"] = { "Desideri plasmare le ossa della Madre Terra in strumenti che aiuteranno l'⟦Horde=Orda⟧. Bene, bene. Segui il sentiero a nord fuori dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ finché non arrivi all'ascensore che porta in cima a ⟦Thunder Bluff=Picco del Tuono⟧. Lì un Guardiano del Picco potrà aiutarti ancora.", "." },
  ["2fb1ec35d1aca8ea"] = { "Addio a te, e che l'ombra ti protegga sempre!", "." },
  ["2fb6886701de535d"] = { "Fa' la tua parte pe' tener pulito il ⟦Deeprun Tram=Tram degli Abissi⟧!", "." },
  ["2fb8708cad0ffbe0"] = { "Ehi! Spero per te che tu non sia <andato/andata> troppo lontano!", "." },
  ["2fb94190480b84f7"] = { "Quali ambienti molto stressanti farebbero destabilizzare i Terrigeni?", "." },
  ["2fb9ddd8887f182a"] = { "Puoi dirmi qualcosa di più su questo posto?", "." },
  ["2fbd2013fb3a3b66"] = { "Basta! Niente più birra finché questo pasticcio non sarà sistemato!", "." },
  ["2fc37b7cc6f89a5f"] = { "<Un/Una> {class}, eh? Beh, allora vorrai parlare con Thorfin Stoneshield, laggiù nel Dwarven District. \r\n\nAh, e assicurati di dirgli che se pesto ancora una volta i bisogni del suo famiglio, addestrerà gli altri cacciatori da dietro le sbarre delle ⟦Stockade=Segrete di Roccavento⟧!", "." },
  ["2fc468bce0c332f8"] = { "Vieni dalle ⟦Burning Steppes=Steppe Ardenti⟧? Hai le mie uova di drago nero?", "." },
  ["2fc6c1a97c61b49a"] = { "Hai sentito quella dell'ogre, del goblin e <del/della> {race}?", "." },
  ["2fc8261d9c5d1f74"] = { "Grazie, Tirion. E la tua identità?", "." },
  ["2fce80bb970d0bde"] = { "Aspetta un attimo mentre te lo preparo!", "." },
  ["2fd7b4b0f9ffa335"] = { "Allora, cos'è questa nuova pestilenza?", "." },
  ["2fdde45f9b73019a"] = { "Salute. Sono un'istruttrice dei maghi, e tu sei <un/una> <mago/maga>.", "." },
  ["2fe22e083f9b20d1"] = { "Ah sì, la Scuoiatura. Nessuno maneggia un coltello da scuoiatore meglio di Yonn Deepcut. Lo trovi nella grande tenda all'angolo nord-ovest del villaggio.", "." },
  ["2ff39446e9d63573"] = { "Devo dire che sono colpito, {name}. Quando ho affrontato il mio vilsegugio, ne sono uscito a malapena vivo. Sento che hai il potenziale per diventare uno degli stregoni più potenti di quest'epoca.", "." },
  ["2ffaa63d361ca82c"] = { "Bisogna fare qualcosa per la tribù dei Selvanera.", "." },
  ["2ffbb1f19876b79d"] = { "Nella gita di ieri, Marduk ci ha mostrato che i draghi tollerano la carne di umanoidi uccisi da poco, ma solo se sono morti lentamente e dolorosamente.", "." },
})
